import React, { useState } from "react";
import { Link } from "react-router-dom";
import { FiPlus, FiEye, FiEdit2, FiTrash2, FiUserCheck } from "react-icons/fi";
import DashboardLayout from "../../layouts/DashboardLayout";
import Card from "../../components/Card";
import DataTable from "../../components/DataTable";
import SearchBar from "../../components/SearchBar";
import Pagination from "../../components/Pagination";
import ConfirmDialog from "../../components/ConfirmDialog";
import { useApiResource } from "../../hooks/useApiResource";
import { instructorApi } from "../../api/instructorApi";
import { useToast } from "../../context/ToastContext";
import { extractErrorMessage } from "../../api/axios";
import { fullName, formatDate } from "../../utils/formatters";

export default function Instructors() {
  const toast = useToast();
  const {
    rows, total, page, setPage, pageSize, search, setSearch,
    sortKey, sortDir, handleSort, isLoading, error, refetch
  } = useApiResource(instructorApi.getAll, { pageSize: 10, initialSort: "last_name" });

  const [deleteTarget, setDeleteTarget] = useState(null);
  const [isDeleting, setIsDeleting] = useState(false);

  async function confirmDelete() {
    setIsDeleting(true);
    try {
      await instructorApi.remove(deleteTarget.id);
      toast.success("Instructor deleted successfully");
      setDeleteTarget(null);
      refetch();
    } catch (err) {
      toast.error(extractErrorMessage(err, "Unable to delete this instructor."));
    } finally {
      setIsDeleting(false);
    }
  }

  const columns = [
    { key: "last_name", label: "Name", sortable: true, render: (r) => <span className="font-medium text-ink">{fullName(r)}</span> },
    { key: "email", label: "Email" },
    { key: "phone", label: "Phone", hideOnMobile: true },
    { key: "department_name", label: "Department", render: (r) => r.department_name || r.department?.name || "—" },
    { key: "created_at", label: "Created At", render: (r) => formatDate(r.created_at), hideOnMobile: true },
    {
      key: "actions",
      label: "Actions",
      render: (r) => (
        <div className="flex items-center gap-1.5">
          <Link to={`/instructors/${r.id}`} className="p-1.5 rounded-md hover:bg-navy-50 text-navy-600" aria-label="View">
            <FiEye size={15} />
          </Link>
          <Link to={`/instructors/${r.id}/edit`} className="p-1.5 rounded-md hover:bg-navy-50 text-navy-600" aria-label="Edit">
            <FiEdit2 size={15} />
          </Link>
          <button
            onClick={() => setDeleteTarget(r)}
            className="p-1.5 rounded-md hover:bg-red-50 text-red-600"
            aria-label="Delete"
          >
            <FiTrash2 size={15} />
          </button>
        </div>
      )
    }
  ];

  return (
    <DashboardLayout>
      <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
        <div className="flex items-center gap-2">
          <div className="h-9 w-9 rounded-lg bg-navy-100 text-navy-700 flex items-center justify-center">
            <FiUserCheck size={16} />
          </div>
          <h1 className="font-display text-xl text-navy-800">Instructors</h1>
        </div>
        <Link
          to="/instructors/create"
          className="flex items-center gap-2 bg-navy-700 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-navy-800 transition"
        >
          <FiPlus size={15} /> Add Instructor
        </Link>
      </div>

      <Card>
        <div className="p-4 border-b border-line">
          <SearchBar value={search} onChange={setSearch} placeholder="Search by name or email..." />
        </div>
        <DataTable
          columns={columns}
          rows={rows}
          isLoading={isLoading}
          error={error}
          sortKey={sortKey}
          sortDir={sortDir}
          onSort={handleSort}
          emptyTitle="No instructors found."
          emptyDescription="Add teaching staff to assign them to courses."
          emptyAction={{ label: "Add Instructor", onClick: () => (window.location.href = "/instructors/create") }}
        />
        <Pagination page={page} pageSize={pageSize} total={total} onPageChange={setPage} />
      </Card>

      <ConfirmDialog
        isOpen={Boolean(deleteTarget)}
        onClose={() => setDeleteTarget(null)}
        onConfirm={confirmDelete}
        isLoading={isDeleting}
        title="Delete instructor?"
        itemLabel={deleteTarget ? fullName(deleteTarget) : ""}
      />
    </DashboardLayout>
  );
}
